const { PDF_PATH } = process.env;
if (!PDF_PATH) throw new Error('Missing PDF_PATH');
globalThis.pdfPath = PDF_PATH;
const { accessSync, constants } = await import('node:fs');
try { accessSync(globalThis.pdfPath, constants.R_OK); } catch (e) { throw new Error('PDF file not accessible'); }

const { readFileSync } = await import('node:fs');
const pdfBytes = readFileSync(globalThis.pdfPath);
const mod = await import('pdf-lib');
const PDFDoc = mod.default || mod;
const pdfDoc = await PDFDoc.load(pdfBytes);
let title = '';
if (typeof pdfDoc.getTitle === 'function') { title = pdfDoc.getTitle(); }
globalThis.heading = title || '';
